const matrix = [
 [[3,0,1,0],[0,3,0,1],[1,0,3,0],[0,1,0,3]],
 [[3,0,1,0],[0,3,0,1],[0,1,3,0],[1,0,0,3]],
 [[3,1,0,0],[0,3,0,1],[1,0,3,0],[0,1,0,3]],
 [[3,0,1,0],[1,3,0,0],[0,0,3,1],[0,1,0,3]],
 [[3,0,1,0],[1,3,0,0],[0,1,3,0],[0,0,1,3]],
 [[3,1,0,0],[1,3,0,0],[0,0,3,1],[0,1,0,3]],
 [[3,0,1,0],[0,3,0,1],[1,0,3,0],[0,1,0,3]]
];
const secretAnswers = {
 '0-1':['Сделать следующий шаг','Найти ответ'],
 '0-2':['Помочь двигаться дальше','Стать надёжной опорой'],
 '0-3':['Шаг за шагом двигаться вперёд','Действовать здесь и сейчас'],
 '1-2':['Разобраться в неизвестном','Разделить с кем-то его заботы'],
 '1-3':['Сначала найти ответ','Сначала сделать самое срочное'],
 '2-3':['Быть опорой столько, сколько потребуется','Прийти на помощь именно тогда, когда ждать нельзя']
};
function getOutcome(answers) {
 if (answers.length!==7 || answers.some(a=>!Number.isInteger(a)||a<0||a>3)) throw new Error('Нужны семь ответов от 0 до 3');
 const scores=[0,0,0,0];
 answers.forEach((a,q)=>matrix[q][a].forEach((v,f)=>scores[f]+=v));
 // При полном равенстве учитываем последний ответ, затем предыдущие.
 const ranked=[0,1,2,3].sort((a,b)=>{
  if(scores[a]!==scores[b]) return scores[b]-scores[a];
  for(let q=6;q>=0;q--){const diff=matrix[q][answers[q]][b]-matrix[q][answers[q]][a];if(diff)return diff;}
  return a-b;
 });
 return {scores,winner:ranked[0],pair:scores[ranked[0]]-scores[ranked[1]]<=2?ranked.slice(0,2).sort((a,b)=>a-b):null};
}

